def join_gpxs(xmls: Iterable[AnyStr]) ->str:
    xmls_list = list(xmls)
    if not xmls_list:
        return ""

    # Parse the first XML to use as the base
    dom = mod_minidom.parseString(xmls_list[0])
    gpx_node: Any = _find_gpx_node(dom)

    if not gpx_node:
        return dom.toxml()

    # Process remaining XMLs and append their elements
    for xml in xmls_list[1:]:
        other_dom = mod_minidom.parseString(xml)
        other_gpx_node: Any = _find_gpx_node(other_dom)

        if other_gpx_node:
            # Copy all child nodes from other GPX to main GPX
            for child_node in list(other_gpx_node.childNodes):
                # Import the node into the main document
                imported_node = dom.importNode(child_node, True)
                gpx_node.appendChild(imported_node)

    return dom.toxml()
